const s = event.metadata.query._path;
const parts = s.split(".");        // ["Weather", "Portland", "Forecast"]
const middle = parts[1];           // "Portland"
stage.setMetadata("Location", middle);
stage.setValue(event.value);

function isNil(value) {
  // Handle the case where the value is a JSON string like "{\"xsi:nil\":true}"
  let obj = value;
  if (typeof value === "string") {
    try {
      obj = JSON.parse(value);
    } catch (e) {
      return false; // not parseable, treat as a normal string value
    }
  }
  return !!(obj && obj["xsi:nil"] === true);
}

event.value.GustNil = isNil(event.value.Gust);

stage.setValue(event.value);
